import pathlib, ast
for p in sorted(pathlib.Path('agents').glob('*.py')):
 if p.name=='__init__.py': continue
 print('\\n###',p.name)
 src=p.read_text(encoding='utf-8')
 try:
  tree=ast.parse(src)
  for n in tree.body:
   if isinstance(n,ast.ClassDef): print('CLASS',n.name,ast.get_docstring(n))
   elif isinstance(n,(ast.Assign,ast.AnnAssign)):
    targets=n.targets if isinstance(n,ast.Assign) else [n.target]
    for t in targets:
     if isinstance(t,ast.Name) and isinstance(n.value,ast.Constant) and isinstance(n.value.value,str):
      print('STRING',t.id,repr(n.value.value[:1000]))
 except Exception as e: print('parse error',e)
'@ | python -"

